30     // Vertex struct holding position information.
31         struct VertexPosition
32         {
33             VertexPosition() = default;
34 
35             VertexPosition(const VertexPosition&) = default;
36             VertexPosition& operator=(const VertexPosition&) = default;
37 
38             VertexPosition(VertexPosition&&) = default;
39             VertexPosition& operator=(VertexPosition&&) = default;
40 
41             VertexPosition(XMFLOAT3 const& iposition) noexcept
42                 : position(iposition)
43             {
44             }
45 
46             VertexPosition(FXMVECTOR iposition) noexcept
47             {
48                 XMStoreFloat3(&this->position, iposition);
49             }
50 
51             XMFLOAT3 position;
52 
53             static const D3D12_INPUT_LAYOUT_DESC InputLayout;
54 
55         private:
56             static constexpr unsigned int InputElementCount = 1;
57             static const D3D12_INPUT_ELEMENT_DESC InputElements[InputElementCount];
58         };
59 
